import { HttpClient } from '@angular/common/http';
import { timeout } from 'rxjs/operators';
/* eslint-disable max-len */
import { Component, ElementRef, Inject, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Urls } from '../../../../core/common/Urls';
import { GAccount } from '../../../../core/common/GAccount';
import { G } from '../../../../core/common/G';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { ToastController, MenuController } from '@ionic/angular';
import { DOCUMENT } from '@angular/common';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';
import { DomainName } from '../../../../core/utility/PathTools';

@Component({
  selector: 'app-account',
  templateUrl: './account.component.html',
  styleUrls: ['./account.component.scss']
})
export class AccountComponent implements OnInit {

  modes: string[] =
    ['login', 'buyerRegister', 'sellerRegister', 'teacherRegister', 'adminRegister', 'forgetPassword', 'resetPassword', 'TwoFactor', 'Invite'];
  selectedMode = this.modes[0];
  email = '';
  id = '';
  inviteId = '';
  isMobile = true;
  googleBusy = false;

  get isPrimaryMode(): boolean {
    return this.selectedMode === this.modes[0] || this.selectedMode === this.modes[1];
  }

  get modeTitle(): string {
    return this.language.text('account.mode.' + this.selectedMode + '.title');
  }

  get modeKicker(): string {
    return this.selectedMode === this.modes[1] || this.selectedMode === this.modes[8]
      ? this.language.text('account.kickerStart') : this.language.text('account.kicker');
  }

  get modeDescription(): string {
    return this.language.text('account.mode.' + this.selectedMode + '.description');
  }

  get modeIcon(): string {
    return {
      login: 'log-in-outline', buyerRegister: 'person-add-outline',
      sellerRegister: 'storefront-outline', teacherRegister: 'school-outline',
      adminRegister: 'settings-outline', forgetPassword: 'mail-unread-outline',
      resetPassword: 'key-outline', TwoFactor: 'shield-checkmark-outline',
      Invite: 'gift-outline'
    }[this.selectedMode] || 'person-outline';
  }

  constructor(
    @Inject(DOCUMENT) private document: Document,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public toastController: ToastController,
    public language: SiteLanguageService,
    private http: HttpClient,
    public menuCtrl: MenuController
  ) { }

  async toggleAppMenu(): Promise<void> {
    await this.menuCtrl.toggle();
  }

  ngOnInit(): void {

    this.isMobile = G.IsAndroid;
    const externalError = this.activatedRoute.snapshot.queryParamMap.get('externalLoginError');
    if (externalError) {
      SharedIonic.toast(this.toastController, externalError === 'admin_password_required'
        ? 'برای حساب ادمین، ابتدا رمز عبور و سپس رمز دوم را وارد کنید.'
        : 'ورود با گوگل فعلاً در دسترس نیست؛ دوباره تلاش کنید یا با رمز عبور وارد شوید.');
      void this.router.navigate([], { queryParams: { externalLoginError: null }, queryParamsHandling: 'merge', replaceUrl: true });
    }

    this.activatedRoute.params.subscribe(params => {

      const msg = params.id;

      if (msg === undefined) {
        return;

      } else {
        if (
          GAccount.IsLoggedIn() &&
          msg === 'forgetPassword' ||
          msg === 'login' ||
          msg === 'buyerRegister' ||
          msg === 'Seller' ||
          msg === 'Admin'
        ) {
          SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
          this.router.navigateByUrl(Urls.HomeUrl);
          return;
        }

        if (msg === 'Seller') {
          this.selectedMode = this.modes[2];
        } else if (msg === 'Teacher') {
          if (GAccount.IsTeacher()) {
            SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
            this.router.navigateByUrl(Urls.HomeUrl);
            return;
          }
          this.selectedMode = this.modes[3];
        } else if (msg === 'Admin') {
          this.selectedMode = this.modes[4];
        } else if (msg === 'forgetPassword') {
          this.selectedMode = this.modes[5];
        } else if (msg === 'resetPassword') {
          this.activatedRoute.queryParams.subscribe(queryParams => {

            const id = queryParams.id;
            const email = queryParams.email;

            if (id === undefined || email === undefined || email === '' || id === '') {

              if (GAccount.IsLoggedIn()) {
                SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
                this.router.navigateByUrl(Urls.HomeUrl);
                return;
              }
              this.selectedMode = this.modes[0];
              return;

            } else {

              GAccount.SignOut();
              this.id = id;
              this.email = email;

              this.selectedMode = this.modes[6];
            }
          });
        } else if (msg === 'TwoFactor') {
          this.activatedRoute.queryParams.subscribe(queryParams => {

            const id = queryParams.id;
            const email = queryParams.email;

            if (id === undefined || email === undefined || email === '' || id === '') {

              if (GAccount.IsLoggedIn()) {
                SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
                this.router.navigateByUrl(Urls.HomeUrl);
                return;
              }
              this.selectedMode = this.modes[0];
              return;

            } else {

              GAccount.SignOut();
              this.id = id;
              this.email = email;

              this.selectedMode = this.modes[7];
            }
          });
        } else if (msg === 'Invite') {

          if (GAccount.IsLoggedIn()) {
            SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
            this.router.navigateByUrl(Urls.HomeUrl);
            return;
          }

          this.activatedRoute.queryParams.subscribe(queryParams => {

            const id = queryParams.id;

            const checkMsgId = parseInt(id.toString(), 10);

            if (Number.isNaN(checkMsgId) || checkMsgId <= 0) {
              SharedIonic.toast(this.toastController, 'لینک معتبر نیست');
              this.router.navigateByUrl(Urls.HomeUrl);
              return;
            }

            if (id === undefined || id === '') {

              this.selectedMode = this.modes[0];
              return;

            } else {

              this.id = id;
              this.selectedMode = this.modes[8];
            }
          });
        } else {
          this.router.navigateByUrl(Urls.AccountUrl);
        }
      }
    });
  }

  // ionViewDidLeave() {

  //   for (let i = 0; i < localStorage.length; i++) {
  //     if (localStorage.key(i) === 'returnUrl') {
  //       localStorage.removeItem('returnUrl');
  //     }
  //   }
  // }

  async onGoogle() {

    if (this.googleBusy) { return; }
    this.googleBusy = true;
    this.http.get<{ google: boolean }>('/api/Account/ExternalLoginProviders').pipe(timeout(10000)).subscribe({
      next: result => {
        this.googleBusy = false;
        if (result.google) { this.document.location.href = DomainName + '/api/Account/GetProvider?provider=Google'; }
        else { SharedIonic.toast(this.toastController, 'ورود با گوگل روی سرور تنظیم نشده است.'); }
      },
      error: () => { this.googleBusy = false; SharedIonic.toast(this.toastController, 'ارتباط با سرویس ورود برقرار نشد؛ دوباره تلاش کنید.'); }
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onRegister() {
    this.selectedMode = this.modes[1];
  }

  onForgetPassword() {
    this.selectedMode = this.modes[5];
  }

  onLogin() {
    this.selectedMode = this.modes[0];
  }
}
